// User entity for the auth-api fixture.
//
// In-memory representation of a registered user. Field set is intentionally
// small to keep the fixture readable; persistence is handled by repository.js.

function makeUser({ id, email, passwordHash, createdAt }) {
  if (!id) throw new Error('user.id is required');
  if (!email) throw new Error('user.email is required');
  if (!passwordHash) throw new Error('user.passwordHash is required');
  return {
    id,
    email,
    passwordHash,
    createdAt: createdAt || new Date().toISOString()
  };
}

function isValidEmail(email) {
  return typeof email === 'string' && /.+@.+\..+/.test(email);
}

module.exports = { makeUser, isValidEmail };

