// In-memory user repository for the fixture. No real DB — just a Map keyed
// by lowercased email. The repository is the single owner of the user
// collection; auth handlers call into it rather than manipulating the
// store directly.

const store = new Map();

function findByEmail(email) {
  if (typeof email !== 'string') return null;
  return store.get(email.toLowerCase()) || null;
}

function findById(id) {
  for (const user of store.values()) {
    if (user.id === id) return user;
  }
  return null;
}

function save(user) {
  store.set(user.email.toLowerCase(), user);
  return user;
}

function update(id, patch) {
  const existing = findById(id);
  if (!existing) return null;
  const updated = { ...existing, ...patch };
  store.set(updated.email.toLowerCase(), updated);
  return updated;
}

function clear() {
  store.clear();
}

module.exports = { findByEmail, findById, save, update, clear };

